#!/usr/bin/env bash
# Builds OCCT with Silico's deterministic recipe (ARCHITECTURE.md, Deterministic kernel):
# pinned release, verified checksum, verified patch series, pinned clang, no fused or
# build-time-folded math, the libm shim in place of the platform math library (private
# to each library), OCCT's input checks compiled in, and no threading library.
#
# Run through pixi so the pinned toolchain is on PATH:  pixi run occt
#
# Builds are shared between checkouts and worktrees: each lives in a cache entry named
# by its stamp (a hash of every input that affects the binaries, with no paths), so a
# second checkout of the same commit reuses it in seconds. This checkout gets:
#   target/occt/install  -> the entry's {include,lib}
#   target/occt/src      -> the entry's patched source
#   target/occt/recipe.env  how other worker C++ (the cxx bridge, PlaneGCS, OndselSolver)
#                           builds the same way; present only while the checks pass
# The cache is $SILICO_OCCT_CACHE/v1 if that's set, else $XDG_CACHE_HOME/silico/occt/v1,
# else ~/.cache/silico/occt/v1. How entries are kept is described in scripts/cache.sh.
set -euo pipefail
# shellcheck disable=SC1091
. "$(dirname "${BASH_SOURCE[0]}")/scripts/platform.sh"

root=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
here=$root/third_party/occt
scripts=$here/scripts
out=$root/target/occt
install=$out/install
# The cache's layout version. Bump it whenever cache.sh changes what it relies on, so a
# checkout running an older cache.sh never prunes entries it doesn't understand. Nothing
# prunes an old layout: build.sh points it out, for deleting once no checkout uses it.
layout=v1
cache_root=${SILICO_OCCT_CACHE:-${XDG_CACHE_HOME:-$HOME/.cache}/silico/occt}
keep_entries=3
mkdir -p "$out" "$cache_root/$layout/downloads"
# Absolute, so links into the cache resolve from anywhere.
cache_root=$(cd "$cache_root" && pwd -P)
cache=$cache_root/$layout

read_key() { sed -n "s/^$1=//p" "$here/VERSION"; }
tag=$(read_key tag)
url=$(read_key url)
sha256=$(read_key sha256)

# The recipe's compiler flags.
#   -ffp-contract=off: no fused multiply-add.
#   -fmath-errno and -fno-builtin-<fn> for every inexact math function in
#     scripts/inexact-math.txt: clang never evaluates them at build time with the build
#     machine's library (fold-canary.sh proves it). Targeted, not a blanket -fno-builtin,
#     so exact builtins like sqrt and memcpy stay inline.
#   -stdlib=libc++: the pinned C++ library.
no_builtins=$(awk '!/^#/ && NF {printf "-fno-builtin-%s -fno-builtin-%sf -fno-builtin-%sl ", $1, $1, $1}' "$scripts/inexact-math.txt")
cflags="-ffp-contract=off -fmath-errno ${no_builtins}-stdlib=libc++"

case "$(uname -s)-$(uname -m)" in
  Darwin-arm64)
    triple=aarch64-apple-darwin
    # Apple's ld: lld 21 can't read the macOS 27 SDK.
    ldflags="-fuse-ld=ld -stdlib=libc++"
    hide_flag() { echo "-Wl,-unexported_symbols_list,$1"; }
    hide_list_name=shim-symbols.txt
    defined_syms() { xcrun nm -gU "$1" | awk '{print $NF}'; }
    toolchain_extra() { xcrun --show-sdk-version; ld -v 2>&1 | head -1; }
    ;;
  Linux-x86_64)
    triple=x86_64-unknown-linux-gnu
    ldflags="-fuse-ld=lld -stdlib=libc++"
    hide_flag() { echo "-Wl,--version-script=$1"; }
    hide_list_name=shim-symbols.map
    defined_syms() { nm -g --defined-only "$1" | awk '{print $NF}'; }
    toolchain_extra() { ldd --version 2>&1 | head -1; }
    ;;
  *)
    echo "occt: unsupported platform $(uname -s)-$(uname -m)" >&2
    exit 1
    ;;
esac

# Everything that affects the result. A change to any of it forces a rebuild. The
# toolchain part lists exact package versions, not paths, so it's the same in every
# checkout of the same commit, which is what lets checkouts share builds.
stamp=$(
  {
    cat "$here/VERSION" "$here/series" "$0" "$scripts/platform.sh" "$scripts/inexact-math.txt"
    while read -r p; do cat "$here/patches/$p"; done < "$here/series"
    cat "$here/libm-shim/Cargo.toml" "$here/libm-shim/Cargo.lock" "$here/libm-shim/src/lib.rs"
    cat "$root/rust-toolchain.toml"
    rustc -V
    clang++ --version | head -1
    ls "$CONDA_PREFIX/conda-meta" | grep '\.json$'
    toolchain_extra
    echo "$triple $cflags $ldflags"
  } | sha256_of | cut -d' ' -f1
)

# Point this checkout at the cache entry, if it's there and valid. Real directories left
# by older layouts of this script are removed first, since `ln -sfn` onto a directory
# would link inside it.
use_entry() {
  local name
  for name in install src downloads build shim-target; do
    if [ -e "$out/$name" ] && [ ! -L "$out/$name" ]; then rm -rf "${out:?}/$name"; fi
  done
  bash "$scripts/cache.sh" use "$cache" "$stamp" "$out"
}

# The recipe, for other worker C++ to build the same way (M0.4 onwards). Written from
# current paths on every invocation, so moving the checkout never leaves stale paths.
write_recipe() {
  cat > "$1" <<EOF
# Generated by third_party/occt/build.sh, and present only if its checks last passed.
# Build worker C++ with this compiler and these flags. A shared library links the shim
# object privately (the hide flag); executables link it directly (ARCHITECTURE.md).
SILICO_CXX="$(command -v clang++)"
SILICO_CXXFLAGS="$cflags"
SILICO_LDFLAGS="$ldflags"
SILICO_LIBM_SHIM="$install/lib/silico_libm_shim.o"
SILICO_SHIM_HIDE_FLAG="$(hide_flag "$install/share/silico/$hide_list_name")"
EOF
}

# The checks run on every invocation, even when the build is up to date: they take
# seconds, and a change to a check must apply to the existing build too.
run_checks() {
  # shellcheck disable=SC2086
  bash "$scripts/fold-canary.sh" $cflags
  bash "$scripts/verify-patches.sh" "$out/src"
  bash "$scripts/check-math-imports.sh" "$install/lib"
  # shellcheck disable=SC2046
  bash "$scripts/check-shim-hidden.sh" "$install/lib/silico_libm_shim.o" $(ls "$install"/lib/libTK*.dylib "$install"/lib/libTK*.so 2>/dev/null)
  bash "$scripts/check-exceptions.sh"
  # Shared builds must not depend on the checkout or machine that built them.
  bash "$scripts/check-relocatable.sh" "$install" "$cache" "$root" "$HOME"
}

# recipe.env exists only while the checks pass: remove it, check against a fresh copy,
# and publish that copy only on success. A failed check leaves no recipe to trust.
check_and_publish() {
  local recipe=$out/recipe.env
  rm -f "$recipe"
  write_recipe "$recipe.tmp"
  SILICO_RECIPE="$recipe.tmp" run_checks
  mv "$recipe.tmp" "$recipe"
}

bash "$scripts/older-layouts.sh" "$cache_root" "$layout" | while read -r other; do
  echo "occt: note: $other is an older layout of this cache; delete it once no checkout of an older commit uses it"
done

if use_entry; then
  check_and_publish
  echo "occt: up to date ($tag, $triple, shared build ${stamp:0:12})"
  exit 0
fi

# Build in a private directory inside the cache, so a failed or interrupted build never
# leaves a half-written entry and two checkouts building at once can't collide.
work=$(mktemp -d "$cache/.build-XXXXXX")
trap 'rm -rf "$work"' EXIT

# 1. The recipe must stop build-time folding of math with this compiler.
# shellcheck disable=SC2086
bash "$scripts/fold-canary.sh" $cflags

# 2. Fetch and verify the pinned release.
tarball=$cache/downloads/OCCT-$tag.tar.gz
if [ ! -f "$tarball" ]; then
  echo "occt: downloading $tag"
  part=$(mktemp "$cache/downloads/.part-XXXXXX")
  curl -fsSL -o "$part" "$url"
  mv "$part" "$tarball"
fi
actual=$(sha256_of "$tarball" | cut -d' ' -f1)
if [ "$actual" != "$sha256" ]; then
  echo "occt: checksum mismatch for $tarball" >&2
  echo "  expected $sha256" >&2
  echo "  actual   $actual" >&2
  exit 1
fi

# 3. Extract a fresh tree, apply the series, and prove every patch landed. patch(1),
# not git apply: inside Silico's repository, git apply skips patches and exits 0.
mkdir -p "$work/src"
tar -xzf "$tarball" -C "$work/src" --strip-components=1
while read -r p; do
  echo "occt: applying $p"
  patch -d "$work/src" -p1 --forward --batch --silent < "$here/patches/$p"
done < "$here/series"
bash "$scripts/verify-patches.sh" "$work/src"

# 4. Build the libm shim as one self-contained object.
CARGO_TARGET_DIR=$work/shim-target cargo rustc --quiet \
  --manifest-path "$here/libm-shim/Cargo.toml" --release --target "$triple" \
  --crate-type staticlib -- --emit=obj
built=("$work/shim-target/$triple/release/deps/"silico_libm_shim-*.o)
if [ ${#built[@]} -ne 1 ] || [ ! -f "${built[0]}" ]; then
  echo "occt: expected exactly one shim object, found: ${built[*]}" >&2
  exit 1
fi
if [ -n "$(nm -u "${built[0]}")" ]; then
  echo "occt: libm shim object has undefined symbols:" >&2
  nm -u "${built[0]}" >&2
  exit 1
fi

# 5. Keep the shim's symbols private to each library, so nothing outside binds to
# them by accident (on Linux, global symbol lookup would otherwise hand them out).
mkdir -p "$work/install/lib" "$work/install/share/silico"
shim=$work/install/lib/silico_libm_shim.o
cp "${built[0]}" "$shim"
hide_list=$work/install/share/silico/$hide_list_name
case "$triple" in
  *-apple-darwin) defined_syms "$shim" > "$hide_list" ;;
  *) { echo "{ global: *; local:"; defined_syms "$shim" | sed 's/$/;/'; echo "};"; } > "$hide_list" ;;
esac

# 6. Build OCCT's modeling modules with the recipe.
#
# BUILD_RELEASE_DISABLE_EXCEPTIONS=OFF: OCCT's Release default (-DNo_Exception) compiles
# out its input checks, so bad input (a zero scale, a zero-length direction) comes back as
# quiet nonsense instead of a Standard_Failure the worker can turn into a structured error.
#
# -ffile-prefix-map: OCCT puts __FILE__ into some error messages, which would otherwise
# carry this build's random directory (and the user's home path) into the libraries and
# into error text. It only renames paths, so it isn't part of the stamp or the recipe.
prefix_map="-ffile-prefix-map=$work=occt"
cmake -S "$work/src" -B "$work/build" -G Ninja \
  -DCMAKE_C_COMPILER=clang -DCMAKE_CXX_COMPILER=clang++ \
  -DCMAKE_BUILD_TYPE=Release \
  -DCMAKE_INSTALL_PREFIX="$work/install" \
  -DCMAKE_C_FLAGS="$cflags $prefix_map" -DCMAKE_CXX_FLAGS="$cflags $prefix_map" \
  -DCMAKE_SHARED_LINKER_FLAGS="$ldflags $(hide_flag "$hide_list")" \
  -DCMAKE_CXX_STANDARD_LIBRARIES="$shim" \
  -DBUILD_LIBRARY_TYPE=Shared \
  -DBUILD_RELEASE_DISABLE_EXCEPTIONS=OFF \
  -DBUILD_MODULE_FoundationClasses=ON -DBUILD_MODULE_ModelingData=ON -DBUILD_MODULE_ModelingAlgorithms=ON \
  -DBUILD_MODULE_Visualization=OFF -DBUILD_MODULE_ApplicationFramework=OFF -DBUILD_MODULE_DataExchange=OFF \
  -DBUILD_MODULE_Draw=OFF -DBUILD_MODULE_Deprecated=OFF \
  -DUSE_TBB=OFF -DUSE_FREETYPE=OFF -DUSE_OPENGL=OFF -DUSE_TK=OFF -DUSE_FREEIMAGE=OFF \
  -DUSE_RAPIDJSON=OFF -DUSE_DRACO=OFF -DUSE_VTK=OFF -DUSE_GLES2=OFF \
  > "$out/cmake.log" 2>&1 || { tail -30 "$out/cmake.log" >&2; exit 1; }
cmake --build "$work/build" > "$out/build.log" 2>&1 || { grep -E "error|FAILED" "$out/build.log" | head -30 >&2; exit 1; }
cmake --install "$work/build" > "$out/install.log" 2>&1

# 7. Make the build relocatable, so any checkout can use it. Each library finds its OCCT
# siblings in its own directory, not in the building checkout's pixi environment (which
# clang adds on its own). libc++ comes from the loading executable's own pixi environment,
# so a process only ever has one copy; on Linux it's a direct dependency of every
# executable linked with -stdlib=libc++, so it's already loaded when OCCT asks for it.
for f in "$work"/install/lib/libTK*; do
  [ -L "$f" ] || set_rpaths "$f" "$own_dir_rpath"
done
# OCCT's CMake package files and environment scripts name this build's temporary paths,
# and Silico uses neither.
rm -rf "$work/build" "$work/shim-target" "$work/install/lib/cmake" "$work/install/bin"
echo "$stamp" > "$work/install/.stamp"

# 8. Publish the entry. If another checkout published the same stamp first, its build is
# used and this one is discarded.
trap - EXIT
bash "$scripts/cache.sh" publish "$cache" "$stamp" "$work" >/dev/null
if ! use_entry; then
  echo "occt: the build for ${stamp:0:12} isn't in the cache after publishing it" >&2
  exit 1
fi

# 9. No platform math may remain, the shim must stay private, OCCT must throw, and the
# build must be relocatable.
check_and_publish
# Keep the most recently used entries (each about 360 MB), and any a checkout links to.
bash "$scripts/cache.sh" prune "$cache" "$keep_entries"
echo "occt: built $tag for $triple (shared build ${stamp:0:12})"
